        {tile('All-time profit', money(tot.pl), tot.n + ' graded bets', tot.n ? col(tot.pl) : null)}
        {tile('All-time ROI', tot.n ? bkPct(tot.roi) : '-', money(tot.st) + ' staked', tot.n ? col(tot.roi) : null)}
