  const nflSecs = [['today', 'Daily board'], ['board', 'Anytime TD'], ['slides', 'Matchups'], ['dvp', 'Defense vs Position'], ['research', 'Player Research Center'], ['mine', 'My game picks'], ['news', 'Injuries & news'], ['bank', 'Bankroll'], ['card', 'The Card'], ['stats', 'Games & Stats'], ['tools', 'Tools'], ['inj', 'Injuries'], ['about', 'About the model'], ['preds', 'Game picks (ML & spread)']];
  const nbaSecs = [['picks', 'Best 5 today'], ['matchups', 'Matchups'], ['dvp', 'Defense vs Position'], ['research', 'Player Research Center'], ['news', 'Injuries & news'], ['bank', 'Bankroll'], ['record', 'Pick record' + (rec ? ' · ' + rec : '')], ['all', 'All 100 players'], ['gpred', 'Game picks (ML & spread)']];
  const secs = top === 'nfl' ? nflSecs : nbaSecs;
