            {top === 'nba' && nsec !== 'matchups' && nsec !== 'dvp' && nsec !== 'research' && nsec !== 'news' && nsec !== 'bank' && nsec !== 'gpred' && <NbaTab DATA={DATA} view={nsec} noBar />}
